export function imageFixtureBytes(mediaType) {
  const encoded = mediaType === "image/jpeg"
    ? JPEG_BASE64_CHUNKS.join("")
    : BASE64[mediaType];
  if (!encoded) throw new Error(`Unknown image fixture media type "${String(mediaType)}".`);
  const binary = atob(encoded);
  return Uint8Array.from(binary, (character) => character.charCodeAt(0));
}

export const IMAGE_FIXTURE_DIMENSIONS = Object.freeze({ width: 2, height: 3 });
